import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyPhuongTienCuDan = () => {
    const [userRoom, setUserRoom] = useState('');
    const [vehicleList, setVehicleList] = useState([]);
    const [loading, setLoading] = useState(true);

    // State cho form nhập mới
    const [type, setType] = useState('');
    const [plate, setPlate] = useState('');

    useEffect(() => {
        const profile = JSON.parse(localStorage.getItem('userProfile') || '{}');
        const room = profile.room_id || profile.room || '102';
        setUserRoom(room);
        fetchVehicles(room);
    }, []);

    // --- LẤY DANH SÁCH XE TỪ BACKEND/STORAGE ---
    const fetchVehicles = async (room) => {
        setLoading(true);
        // Giả lập gọi API
        setTimeout(() => {
            const allData = JSON.parse(localStorage.getItem('all_vehicles') || '{}');
            setVehicleList(allData[room] || []);
            setLoading(false);
        }, 300);
    };

    // --- HÀM THÊM PHƯƠNG TIỆN (TỐI ƯU CHO BACKEND) ---
    const handleAddVehicle = async () => {
        if (!type || !plate) {
            alert("Vui lòng nhập đầy đủ loại xe và biển số!");
            return;
        }

        const newVehicle = { type, plate };

        try {
            /* SAU NÀY GẮN API:
            await axios.post('/api/vehicles', { room: userRoom, ...newVehicle });
            */

            // HIỆN TẠI: Lưu vào localStorage
            const allData = JSON.parse(localStorage.getItem('all_vehicles') || '{}');
            const roomData = allData[userRoom] || [];
            const updatedData = [...roomData, newVehicle];

            allData[userRoom] = updatedData;
            localStorage.setItem('all_vehicles', JSON.stringify(allData));

            // Cập nhật giao diện
            setVehicleList(updatedData);
            setType('');
            setPlate('');
            alert("Đăng ký phương tiện thành công!");
        } catch (error) {
            alert("Lỗi khi đăng ký phương tiện!");
        }
    };

    return (
        <div style={containerStyle} className="glass-card">
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>🚗 ĐĂNG KÝ PHƯƠNG TIỆN</h2>
                <div style={roomBadge}>Phòng {userRoom}</div>
            </div>

            <div style={contentWrapperStyle}>
                <div style={mainLayout}>

                    {/* KHỐI TRÁI: FORM NHẬP (TRẮNG ĐẶC - RÕ) */}
                    <div style={whiteCardForm}>
                        <div style={roomDisplay}>
                            <span style={{ fontSize: '13px', color: '#8b5e5e', fontWeight: 'bold' }}>ĐĂNG KÝ MỚI</span>
                        </div>

                        <div style={inputGroup}>
                            <label style={labelStyle}>Loại xe:</label>
                            <select style={inputStyle} value={type} onChange={(e) => setType(e.target.value)}>
                                <option value="">-- Chọn loại xe --</option>
                                <option value="Xe máy">Xe máy</option>
                                <option value="Ô tô">Ô tô</option>
                                <option value="Xe đạp điện">Xe đạp điện</option>
                            </select>
                        </div>

                        <div style={inputGroup}>
                            <label style={labelStyle}>Biển số xe:</label>
                            <input 
                                style={inputStyle} 
                                value={plate} 
                                onChange={(e) => setPlate(e.target.value)} 
                                placeholder="VD: 43-K1 123.45" 
                            />
                        </div>

                        <button onClick={handleAddVehicle} style={btnSubmitStyle}>THÊM PHƯƠNG TIỆN</button>
                    </div>

                    {/* KHỐI PHẢI: DANH SÁCH ĐÃ ĐĂNG KÝ (TRẮNG ĐẶC - RÕ) */}
                    <div style={whiteCardList}>
                        <h3 style={{ color: '#8b5e5e', fontSize: '16px', textAlign: 'center', marginBottom: '20px' }}>PHƯƠNG TIỆN ĐÃ ĐĂNG KÝ</h3>

                        {loading ? (
                            <div style={statusMsg}>Đang tải...</div>
                        ) : (
                            <div style={{ overflowY: 'auto', flex: 1 }} className="custom-scrollbar">
                                {vehicleList.length > 0 ? vehicleList.map((v, i) => (
                                    <div key={i} style={vehicleItem}>
                                        <div>
                                            <div style={{fontWeight: 'bold', color: '#333'}}>{v.type}</div>
                                            <div style={plateDisplay}>{v.plate}</div>
                                        </div>
                                        <div style={statusBadge}>Đã duyệt</div>
                                    </div>
                                )) : (
                                    <div style={statusMsg}>Chưa có xe nào</div>
                                )}
                            </div>
                        )}
                    </div>

                </div>
            </div>

            <style>{`
                @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #eee; border-radius: 10px; }
            `}</style>
        </div>
    );
};

// --- STYLES ĐỒNG BỘ 100% XEMHOADON ---
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const headerStyle = { padding: '20px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'rgba(0,0,0,0.3)' };
const roomBadge = { padding: '6px 15px', background: '#fff', borderRadius: '12px', color: '#8b5e5e', fontWeight: 'bold' };
const contentWrapperStyle = { flex: 1, display: 'flex', padding: '25px', overflow: 'hidden' };
const mainLayout = { display: 'flex', gap: '25px', width: '100%', animation: 'fadeIn 0.4s' };

const whiteCardForm = { width: '350px', backgroundColor: '#fff', borderRadius: '30px', padding: '30px', boxShadow: '0 15px 35px rgba(0,0,0,0.2)' };
const whiteCardList = { flex: 1, backgroundColor: '#fff', borderRadius: '30px', padding: '30px', boxShadow: '0 15px 35px rgba(0,0,0,0.15)', display: 'flex', flexDirection: 'column' };

const roomDisplay = { textAlign: 'center', padding: '12px', background: '#fdf3f3', borderRadius: '15px', marginBottom: '20px', border: '2px dashed #8b5e5e' };
const inputGroup = { marginBottom: '15px' };
const labelStyle = { display: 'block', fontWeight: 'bold', marginBottom: '8px', color: '#666', fontSize: '13px' };
const inputStyle = { width: '100%', padding: '12px', borderRadius: '12px', border: '1px solid #ddd', outline: 'none' };
const btnSubmitStyle = { width: '100%', padding: '15px', borderRadius: '15px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px' };

const vehicleItem = { padding: '15px', background: '#f9f9f9', borderRadius: '15px', marginBottom: '10px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderLeft: '5px solid #8b5e5e' };
const plateDisplay = { fontSize: '18px', fontWeight: '900', color: '#8b5e5e', marginTop: '3px' };
const statusBadge = { fontSize: '10px', padding: '4px 8px', background: '#e6f4ea', color: '#1e7e34', borderRadius: '8px', fontWeight: 'bold' };
const statusMsg = { textAlign: 'center', color: '#ccc', marginTop: '50px' };

export default QuanLyPhuongTienCuDan;
